```python
def publish(bus, topic, payload):
    # Rule 1: Call each subscriber in bus.subscribers[topic], in order, with a single argument: payload.
    delivered = 0
    if topic in bus.subscribers:
        for subscriber in bus.subscribers[topic]:
            try:
                subscriber(payload)
                delivered += 1
            except Exception:
                pass

    # Rule 2: Then call each wildcard subscriber registered under the topic "*", in order, with two arguments: (topic, payload).
    if "*" in bus.subscribers:
        for subscriber in bus.subscribers["*"]:
            try:
                subscriber(topic, payload)
                delivered += 1
            except Exception:
                pass

    # Rule 4: If there was no successful delivery, append the tuple (topic, payload) to bus.dead_letters.
    if delivered == 0:
        bus.dead_letters.append((topic, payload))

    # Return the number of successful deliveries.
    return delivered
```The function returns the number of successful deliveries.

