```python
def upload_all(uploader, records):
    max_batch = uploader.max_batch
    failed_ids = []

    for i in range(0, len(records), max_batch):
        batch = records[i:i + max_batch]
        sent = uploader.send(batch)
        if sent:
            continue
        else:
            failed_ids.extend(sent)

    if failed_ids:
        retry_batch = failed_ids
        retry_records = []
        for record in records:
            if record["id"] in retry_batch:
                retry_records.append(record)

        for j in range(0, len(retry_records), max_batch):
            retry_batch = retry_records[j:j + max_batch]
            retry_sent = uploader.send(retry_batch)
            if retry_sent:
                continue
            else:
                failed_ids.extend(retry_batch)

    return sorted(failed_ids)
```

This code follows the rules: send records in batches, and retry only once if any records still fail. It returns the sorted list of IDs that are still failing.

