def is_valid_label(label):
    # Rule 1: Length is between 6 and 12 characters (inclusive)
    if not (6 <= len(label) <= 12):
        return False

    # Rule 2: First character is a lowercase letter (a-z)
    if not ('a' <= label[0] <= 'z'):
        return False

    # Rule 3: Contains only lowercase letters, digits, and underscore (_)
    if not all(c.islower() or c.isdigit() or c == '_' for c in label):
        return False

    # Rule 4: Contains at least one digit
    if not any(c.isdigit() for c in label):
        return False

    # Rule 5: No two underscores in a row ("__")
    if '__' in label:
        return False

    # Rule 6: Does not end with an underscore
    if label.endswith('_'):
        return False

    return True
```The function returns True if the label follows all the rules.

