def is_valid_password(password, username):
    # Rule 1: At least 10 characters
    if len(password) < 10:
        return False

    # Rule 2: At least 2 digits (0-9)
    if not any(char.isdigit() for char in password):
        return False

    # Rule 3: At least one symbol: !, @, or #
    symbols = {'!', '@', '#'}
    if not any(char in symbols for char in password):
        return False

    # Rule 4: No character appears 3 or more times in a row
    for i in range(len(password) - 2):
        if password[i] == password[i+1] == password[i+2]:
            return False

    # Rule 5: No character matches the username (case-insensitive)
    if username.lower() in password.lower():
        return False

    return True
```The function returns True if the password satisfies all Vireo rules for the given username.

